use crate::scanner::{ArgKind, CrateApi, RetKind};

#[derive(Debug, Clone)]
pub struct SyncSummary {
    pub crate_count: usize,
    pub struct_count: usize,
    pub enum_count: usize,
    pub fn_count: usize,
}

pub fn emit_crate_bridge(apis: &[CrateApi]) -> (String, SyncSummary) {
    let mut out = String::from(
        "// AUTO-GENERATED BY `striv sync` - DO NOT EDIT MANUALLY\n\n\
         #![allow(non_camel_case_types, unused_mut, dead_code, unused_imports)]\n\
         use slotmap::{Key as SlotKey, KeyData, SlotMap, new_key_type};\n\
         use std::cell::RefCell;\n\n",
    );

    let mut symbols: Vec<(String, String, usize)> = Vec::new();
    let mut constants: Vec<(String, i64)> = Vec::new();
    let mut struct_count = 0;
    let mut enum_count = 0;

    for api in apis {
        let cr = &api.crate_name;

        // 1. Emit SlotMap vault for each struct used in methods
        let mut used_structs: Vec<String> = Vec::new();
        for m in &api.methods {
            if let Some(s) = &m.struct_name {
                if !used_structs.contains(s) {
                    used_structs.push(s.clone());
                }
            }
            if let RetKind::Handle(s) | RetKind::ResultHandle(s) = &m.ret {
                if !used_structs.contains(s) {
                    used_structs.push(s.clone());
                }
            }
            for arg in &m.args {
                if let ArgKind::Handle(s) = arg {
                    if !used_structs.contains(s) {
                        used_structs.push(s.clone());
                    }
                }
            }
        }

        for s in &used_structs {
            struct_count += 1;
            let key_ty = format!("AutoKey_{}_{}", cr, s);
            let vault = format!("VAULT_{}_{}", cr.to_uppercase(), s.to_uppercase());
            out.push_str(&format!(
                "new_key_type! {{ pub struct {key_ty}; }}\n\
                 thread_local! {{\n\
                     static {vault}: RefCell<SlotMap<{key_ty}, {cr}::{s}>> = RefCell::new(SlotMap::with_key());\n\
                 }}\n\n"
            ));
        }

        // 2. Emit enum converters & constants
        for en in &api.enums {
            enum_count += 1;
            let conv_fn = format!("auto_enum_{}_{}", cr, en.name.to_lowercase());
            out.push_str(&format!(
                "#[allow(dead_code)]\nfn {conv_fn}(v: i64) -> {cr}::{en_name} {{\n    match v {{\n",
                en_name = en.name
            ));
            for (idx, var) in en.variants.iter().enumerate() {
                out.push_str(&format!(
                    "        {} => {}::{}::{},\n",
                    idx, cr, en.name, var
                ));
                constants.push((format!("{}__{}", en.name, var), idx as i64));
            }
            out.push_str(&format!(
                "        _ => {}::{}::{},\n    }}\n}}\n\n",
                cr, en.name, en.variants[0]
            ));
        }

        // 3. Emit extern "C" wrappers for each supported method / function
        for m in &api.methods {
            let (striv_name, c_sym) = match &m.struct_name {
                Some(s) => (
                    format!("{}__{}", s, m.name),
                    format!("striv_auto_{}_{}_{}", cr, s.to_lowercase(), m.name),
                ),
                None => (m.name.clone(), format!("striv_auto_{}_{}", cr, m.name)),
            };

            let mut c_params = Vec::new();
            if m.receiver.is_some() {
                c_params.push("self_h: i64".to_string());
            }
            for (i, _) in m.args.iter().enumerate() {
                c_params.push(format!("arg{}: i64", i));
            }

            let param_count = c_params.len();
            symbols.push((striv_name, c_sym.clone(), param_count));

            out.push_str(&format!(
                "#[unsafe(no_mangle)]\npub extern \"C\" fn {}({}) -> i64 {{\n",
                c_sym,
                c_params.join(", ")
            ));

            // Prepare converted arguments
            let mut call_args = Vec::new();
            for (i, arg) in m.args.iter().enumerate() {
                match arg {
                    ArgKind::Int(ty) => call_args.push(format!("arg{} as {}", i, ty)),
                    ArgKind::Bool => call_args.push(format!("arg{} != 0", i)),
                    ArgKind::Float(ty) => {
                        call_args.push(format!("f64::from_bits(arg{} as u64) as {}", i, ty))
                    }
                    ArgKind::StrRef => {
                        out.push_str(&format!(
                            "    let s_arg{i} = unsafe {{ &*(arg{i} as *const String) }};\n"
                        ));
                        call_args.push(format!("s_arg{i}.as_str()"));
                    }
                    ArgKind::U32Slice => {
                        out.push_str(&format!(
                            "    let v_arg{i}: Vec<u32> = unsafe {{ &*(arg{i} as *const Vec<i64>) }}.iter().map(|&x| x as u32).collect();\n"
                        ));
                        call_args.push(format!("&v_arg{i}"));
                    }
                    ArgKind::Enum(en_name) => {
                        call_args.push(format!(
                            "auto_enum_{}_{}(arg{})",
                            cr,
                            en_name.to_lowercase(),
                            i
                        ));
                    }
                    ArgKind::Handle(h_struct) => {
                        let vault =
                            format!("VAULT_{}_{}", cr.to_uppercase(), h_struct.to_uppercase());
                        let key_ty = format!("AutoKey_{}_{}", cr, h_struct);
                        out.push_str(&format!(
                            "    let h_arg{i} = {vault}.with(|v| v.borrow_mut().remove({key_ty}::from(KeyData::from_ffi(arg{i} as u64))).expect(\"Invalid handle\"));\n"
                        ));
                        call_args.push(format!("h_arg{i}"));
                    }
                    ArgKind::HandleRef(_, _) => {
                        // Skip emitting invalid borrows by returning 0 if reached
                        call_args.push("unreachable!()".to_string());
                    }
                }
            }

            let args_joined = call_args.join(", ");
            let call_expr = match (&m.struct_name, m.receiver) {
                (Some(s), Some(is_mut)) => {
                    let vault = format!("VAULT_{}_{}", cr.to_uppercase(), s.to_uppercase());
                    let key_ty = format!("AutoKey_{}_{}", cr, s);
                    let borrow = if is_mut { "borrow_mut" } else { "borrow" };
                    let getter = if is_mut { "get_mut" } else { "get" };
                    format!(
                        "{vault}.with(|v| {{ let mut map = v.{borrow}(); let obj = map.{getter}({key_ty}::from(KeyData::from_ffi(self_h as u64))).expect(\"Invalid handle\"); obj.{}({args_joined}) }})",
                        m.name
                    )
                }
                (Some(s), None) => format!("{cr}::{s}::{}({args_joined})", m.name),
                (None, _) => format!("{cr}::{}({args_joined})", m.name),
            };

            match &m.ret {
                RetKind::Unit => out.push_str(&format!("    {};\n    0\n", call_expr)),
                RetKind::Int => out.push_str(&format!("    ({}) as i64\n", call_expr)),
                RetKind::Bool => {
                    out.push_str(&format!("    if {} {{ 1 }} else {{ 0 }}\n", call_expr))
                }
                RetKind::Float => {
                    out.push_str(&format!("    (({}) as f64).to_bits() as i64\n", call_expr))
                }
                RetKind::Handle(s) => {
                    let vault = format!("VAULT_{}_{}", cr.to_uppercase(), s.to_uppercase());
                    out.push_str(&format!(
                        "    let res = {};\n    {vault}.with(|v| v.borrow_mut().insert(res).data().as_ffi() as i64)\n",
                        call_expr
                    ));
                }
                RetKind::ResultHandle(s) => {
                    let vault = format!("VAULT_{}_{}", cr.to_uppercase(), s.to_uppercase());
                    out.push_str(&format!(
                        "    let res = ({}).expect(\"Rust call returned Err\");\n    {vault}.with(|v| v.borrow_mut().insert(res).data().as_ffi() as i64)\n",
                        call_expr
                    ));
                }
                RetKind::ResultUnit => {
                    out.push_str(&format!(
                        "    if ({}).is_ok() {{ 1 }} else {{ 0 }}\n",
                        call_expr
                    ));
                }
            }
            out.push_str("}\n\n");
        }
    }

    out.push_str("pub fn exported_symbols() -> &'static [(&'static str, &'static str, *const u8, usize)] {\n    &[\n");
    for (striv_name, c_sym, param_count) in &symbols {
        out.push_str(&format!(
            "        (\"{}\", \"{}\", {} as *const u8, {}),\n",
            striv_name, c_sym, c_sym, param_count
        ));
    }
    out.push_str("    ]\n}\n\n");

    out.push_str("pub fn exported_constants() -> &'static [(&'static str, i64)] {\n    &[\n");
    for (c_name, val) in &constants {
        out.push_str(&format!("        (\"{}\", {}),\n", c_name, val));
    }
    out.push_str("    ]\n}\n");

    let summary = SyncSummary {
        crate_count: apis.len(),
        struct_count,
        enum_count,
        fn_count: symbols.len(),
    };
    (out, summary)
}
